import os
import posixpath
import typing as ta

from .exports import resolve_package_export
from .models import GraphVerifyRequest
from .models import GraphVerifyResult
from .models import RewriteRequest
from .models import RewriteResult
from .parsing import parse_module


##


# Version-one output retains this marker so extraction does not churn committed vendor trees.
_GENERATED_HEADER = f'// @generated by {__package__}; do not edit\n'


def iter_import_specifiers(source: str, /) -> ta.Iterator[str]:
    for specifier in parse_module(source).specifiers:
        yield specifier.value


def package_directory(name: str, /) -> str:
    return posixpath.join('packages', name)


def _split_package_specifier(specifier: str, /) -> tuple[str, str]:
    if specifier.startswith('@'):
        parts = specifier.split('/')
        if len(parts) < 2:
            raise ValueError(f'Invalid scoped package import: {specifier}')
        return '/'.join(parts[:2]), '/'.join(parts[2:])
    package_name, _, suffix = specifier.partition('/')
    return package_name, suffix


def _resolve_bare_import(specifier: str, request: RewriteRequest, /) -> str:
    package_name, suffix = _split_package_specifier(specifier)
    if package_name not in request.package_names:
        raise ValueError(f'Unresolved bare import: {specifier}')

    exports = request.package_exports.get(package_name)
    if exports is None:
        target_relative = suffix or 'index.js'
        if suffix and not posixpath.splitext(target_relative)[1]:
            target_relative += '.js'
    else:
        try:
            target_relative = resolve_package_export(exports, suffix)
        except ValueError as exc:
            raise ValueError(f'{exc} (imported as {specifier})') from None
    return posixpath.join(package_directory(package_name), target_relative)


def _split_url_suffix(specifier: str, /) -> tuple[str, str]:
    indexes = [index for separator in ('?', '#') if (index := specifier.find(separator)) >= 0]
    if not indexes:
        return specifier, ''
    index = min(indexes)
    return specifier[:index], specifier[index:]


def rewrite_module(request: RewriteRequest, /) -> RewriteResult:
    parsed = parse_module(request.source)
    if parsed.dynamic_import:
        raise ValueError(f'Dynamic import is not allowed in vendored ESM: {request.source_path}')

    source_origin = request.source_origin or request.source_path
    replacements = []
    for specifier in parsed.specifiers:
        value = specifier.value
        if value.startswith('.'):
            if source_origin == request.source_path:
                continue
            path, url_suffix = _split_url_suffix(value)
            target = posixpath.normpath(posixpath.join(posixpath.dirname(source_origin), path))
            replacement = posixpath.relpath(target, posixpath.dirname(request.source_path))
            if not replacement.startswith('.'):
                replacement = './' + replacement
            replacement += url_suffix
        else:
            if value.startswith(('/', '#')) or ':' in value:
                raise ValueError(f'Unsupported import in {request.source_path}: {value}')
            target = _resolve_bare_import(value, request)
            replacement = posixpath.relpath(target, posixpath.dirname(request.source_path))
            if not replacement.startswith('.'):
                replacement = './' + replacement
        replacements.append((specifier.start, specifier.end, replacement))

    rewritten = request.source
    for start, end, replacement in reversed(replacements):
        rewritten = rewritten[:start] + replacement + rewritten[end:]
    if rewritten.endswith('\n'):
        lines = rewritten.splitlines(keepends=True)
        if lines and lines[-1].lstrip().startswith('//# sourceMappingURL='):
            rewritten = ''.join(lines[:-1])
    return RewriteResult(source=_GENERATED_HEADER + rewritten)


def _module_files(root: str, /) -> frozenset[str]:
    modules = set()
    for directory, directories, names in os.walk(root):
        for name in (*directories, *names):
            path = os.path.join(directory, name)
            if os.path.islink(path):
                relative = os.path.relpath(path, root).replace(os.sep, '/')
                raise ValueError(f'Symbolic link is not allowed in vendor tree: {relative}')
        for name in names:
            if name.endswith(('.js', '.mjs')):
                path = os.path.join(directory, name)
                modules.add(os.path.relpath(path, root).replace(os.sep, '/'))
    return frozenset(modules)


def verify_graph(request: GraphVerifyRequest, /) -> GraphVerifyResult:
    modules = _module_files(request.root)
    import_count = 0
    for relative_path in sorted(modules):
        path = os.path.join(request.root, *relative_path.split('/'))
        try:
            with open(path, encoding='utf-8') as file:
                source = file.read()
            parsed = parse_module(source)
        except (UnicodeDecodeError, ValueError) as exc:
            raise ValueError(f'Invalid vendored ESM in {relative_path}: {exc}') from None
        if parsed.dynamic_import:
            raise ValueError(f'Dynamic import remains in {relative_path}')

        for specifier in parsed.specifiers:
            import_count += 1
            if not specifier.value.startswith('.'):
                raise ValueError(f'Bare import remains in {relative_path}: {specifier.value}')
            target_specifier, _ = _split_url_suffix(specifier.value)
            if '\\' in target_specifier or '%' in target_specifier:
                raise ValueError(f'Unsafe import target in {relative_path}: {specifier.value}')
            target = posixpath.normpath(posixpath.join(posixpath.dirname(relative_path), target_specifier))
            if target.startswith(('../', '/')) or target in ('.', '..'):
                raise ValueError(f'Import escapes vendor tree: {relative_path} -> {specifier.value}')
            if target not in modules:
                raise ValueError(f'Import target does not exist: {relative_path} -> {specifier.value}')

    return GraphVerifyResult(
        module_count=len(modules),
        import_count=import_count,
    )
